"""Visual reading order and captions for the report-based case studies."""
def L(value):
    parts=value.split(' | ')
    assert len(parts)==4,value
    return dict(zip(('en','pt','fr','es'),parts))
def F(file,title,caption):
    return dict(file='img/projects/'+file,title=L(title),caption=L(caption))

